const src=$input.first()?.json??{};
const msg=src.message||src.edited_message||src.callback_query?.message||{};
const chatId=String(msg.chat?.id||'').trim();
if(!chatId)return [];
const raw=String(src.callback_query?.data||msg.text||msg.caption||'').trim();
const k=raw.toLowerCase();
const S=$getWorkflowStaticData('global');
S.vaira=S.vaira||{ownerChatId:null,target:'MONA',inputMode:null,pending:{},approved:{}};
const V=S.vaira;
if(!V.ownerChatId){
  if(!['/start','/menu','start','menu'].includes(k))
    return [{json:{action:'REPLY',chatId,text:'🔐 Trimite /start pentru a lega VAIRA de acest chat.',menu:false}}];
  V.ownerChatId=chatId;
}
if(chatId!==String(V.ownerChatId))return [];
if(['/start','/menu','start','menu','🎛️ menu'].includes(k))
  return [{json:{action:'REPLY',chatId,menu:true,text:'🎛️ VAIRA CONTROL CENTER\n\nTarget: '+V.target+'\nMode: PHOTO\nSocial publish: OFF / TEST SAFE\n\nAlege personajul, apoi ➕ CREATE.'}}];
if(k==='🌙 mona'||k==='mona'){V.target='MONA';return [{json:{action:'REPLY',chatId,menu:true,text:'🌙 MONA selectată.'}}];}
if(k==='🖤 naya'||k==='naya'){V.target='NAYA';return [{json:{action:'REPLY',chatId,menu:true,text:'🖤 NAYA selectată.'}}];}
if(k==='➕ create'||k==='create'||k==='/create'){V.inputMode='CREATE';return [{json:{action:'REPLY',chatId,menu:false,text:'✍️ Trimite descrierea fotografiei pentru '+V.target+'.'}}];}
if(k==='📊 status'||k==='status'||k==='/status'){
  const p=V.pending?.[chatId]||null;
  return [{json:{action:'REPLY',chatId,menu:true,text:'📊 VAIRA STATUS\nTarget: '+V.target+'\nPending preview: '+(p?'YES':'NO')+'\nSocial publish: OFF / TEST SAFE'}}];
}
if(k==='vaira_approve'){
  const p=V.pending?.[chatId]||null;
  if(!p)return [{json:{action:'REPLY',chatId,menu:true,text:'⚠️ Nu există preview pending.'}}];
  V.approved[chatId]={...p,approvedAt:new Date().toISOString()};
  delete V.pending[chatId];
  return [{json:{action:'REPLY',chatId,menu:true,text:'✅ APPROVED • '+p.target+'\nPreview aprobat. Social publish rămâne OFF până validăm testul.'}}];
}
if(k==='vaira_reject'){
  const p=V.pending?.[chatId]||null; delete V.pending[chatId];
  return [{json:{action:'REPLY',chatId,menu:true,text:p?'❌ Preview respins. Nu se publică nimic.':'⚠️ Nu există preview pending.'}}];
}
if(k==='vaira_regenerate'){
  const p=V.pending?.[chatId]||null;
  if(!p)return [{json:{action:'REPLY',chatId,menu:true,text:'⚠️ Nu există preview pending.'}}];
  return [{json:{action:'GENERATE',chatId,target:p.target,prompt:p.prompt,generationAttempt:Number(p.generationAttempt||1)+1,ack:'🔄 Regenerez '+p.target+'...'}}];
}
if(V.inputMode==='CREATE'&&raw){
  V.inputMode=null;
  return [{json:{action:'GENERATE',chatId,target:V.target,prompt:raw,generationAttempt:1,ack:'🧠 Pornesc generarea reală pentru '+V.target+'...'}}];
}
return [{json:{action:'REPLY',chatId,menu:true,text:'Folosește meniul VAIRA.'}}];

const x=$('VAIRA • Generate Gate').item.json;
const isMona=x.target==='MONA';
const r=isMona?{
 face:'https://d2ol7oe51mr4n9.cloudfront.net/user_3IbQt5kDpDnK6Ec0xXtin2Yvkk5/48a13032-b0be-48aa-bdf6-2ea0400b5ac3.png',
 identity:'Mona Moon Ice Lady. Match the canonical face and body identity. Very long curly blue-black hair with icy gray-blue streak, brown eyes, light natural skin, slim-toned feminine body, preserve canonical tattoos, realistic skin and anatomy, no identity drift.'
}:{
 face:'https://d2ol7oe51mr4n9.cloudfront.net/user_3IbQt5kDpDnK6Ec0xXtin2Yvkk5/716374a7-3cf5-479d-9fa1-8c9052d040ca.png',
 identity:'Naya Noire Fire Priestess. Match the canonical face and body identity. Very long dark hair with burgundy accents, hazel-brown eyes, beauty mark near upper lip, piercings and phoenix/fire tattoo identity, realistic skin and anatomy, no identity drift.'
};
const requestBody={
 image_url:r.face,
 prompt:r.identity+' SCENE: '+String(x.prompt||'Natural premium Amsterdam lifestyle scene')+'. Exact same person. Photorealistic, tasteful, non-explicit, platform-safe.',
 batch_size:1,resolution:'720p',aspect_ratio:'3:4',enhance_prompt:true
};
return [{json:{...x,mediaType:'PHOTO',hfEndpoint:'https://api.higgsfield.ai/higgsfield-ai/soul/v2/image-to-image',requestBody}}];

const r=$input.first()?.json??{}; const p=$('VAIRA • Prepare Higgsfield').item.json; const b=r.body??r;
const requestId=b.request_id??b.requestId??b.id??null;
const statusUrl=b.status_url??b.statusUrl??(requestId?'https://api.higgsfield.ai/requests/'+requestId+'/status':null);
if(!requestId&&!statusUrl)return [{json:{...p,hfStatus:'submit_failed',hfError:b.error||b.message||JSON.stringify(b),pollAgain:false}}];
return [{json:{...p,requestId,statusUrl,pollCount:0}}];

const r=$input.first()?.json??{}; const p=$('VAIRA • Wait 5s').item.json; const b=r.body??r;
const st=String(b.status??b.state??'').toLowerCase();
const assetUrl=b.images?.[0]?.url||b.image?.url||b.output?.url||b.result?.url||b.result_url||b.url||null;
const pollCount=Number(p.pollCount||0)+1;
const terminal=['completed','failed','nsfw','canceled','cancelled','submit_failed'];
return [{json:{...p,...b,hfStatus:st||'unknown',assetUrl,pollCount,pollAgain:!terminal.includes(st)&&pollCount<48}}];

const x=$json; const S=$getWorkflowStaticData('global'); S.vaira=S.vaira||{}; S.vaira.pending=S.vaira.pending||{};
S.vaira.pending[String(x.chatId)]={target:x.target,prompt:x.prompt,assetUrl:x.assetUrl,requestId:x.requestId||null,generationAttempt:Number(x.generationAttempt||1),completedAt:new Date().toISOString()};
return [{json:x}];
